/**
 * Extracts frames from a video URL at specified intervals.
 * Note: Browser security (CORS) limits frame extraction from external URLs.
 * Works best with File objects created via URL.createObjectURL(file).
 */
export const extractFramesFromVideo = async (
  videoUrl: string,
  intervalSeconds: number,
  onProgress: (progress: number) => void
): Promise<{ timestamp: number; imageUrl: string }[]> => {
  return new Promise((resolve, reject) => {
    const video = document.createElement('video');
    const canvas = document.createElement('canvas');
    const context = canvas.getContext('2d');
    const frames: { timestamp: number; imageUrl: string }[] = [];

    // Fix: Append to body to prevent aggressive browser garbage collection of decoding pipeline
    // for detached elements, which causes PIPELINE_ERROR_DECODE.
    video.style.display = 'none';
    video.setAttribute('muted', 'true');
    video.setAttribute('playsinline', 'true');
    document.body.appendChild(video);

    // Only set crossOrigin for non-blob and non-data URLs. 
    if (!videoUrl.startsWith('blob:') && !videoUrl.startsWith('data:')) {
      video.crossOrigin = 'anonymous';
    }

    video.src = videoUrl;
    video.defaultMuted = true;
    video.muted = true;
    video.volume = 0; 
    video.playsInline = true;
    video.preload = 'auto';

    if (!context) {
      if (video.parentNode) video.parentNode.removeChild(video);
      reject(new Error("Could not create canvas context"));
      return;
    }

    let currentTime = 0;
    let isFinished = false;

    const cleanup = () => {
      isFinished = true;
      video.onerror = null;
      video.onseeked = null;
      video.onloadedmetadata = null;
      video.pause();
      video.src = "";
      video.load(); // Force release resources
      if (video.parentNode) {
        video.parentNode.removeChild(video);
      }
      video.remove();
    };

    video.onloadedmetadata = () => {
      // Cap resolution for extraction to avoid overwhelming the memory/decoder
      // 1280px is plenty for AI analysis and reduces decode errors significantly
      const MAX_DIM = 1280;
      let width = video.videoWidth;
      let height = video.videoHeight;

      if (width > MAX_DIM || height > MAX_DIM) {
        if (width > height) {
          height = (MAX_DIM / width) * height;
          width = MAX_DIM;
        } else {
          width = (MAX_DIM / height) * width;
          height = MAX_DIM;
        }
      }

      canvas.width = width;
      canvas.height = height;

      // Start processing after a brief delay to ensure decoder is ready
      setTimeout(() => seekAndCapture(), 500);
    };

    video.onerror = (e) => {
      if (isFinished) return;

      // Better error logging
      const errorCode = video.error ? video.error.code : 0;
      const errorMsg = video.error ? video.error.message : "Unknown";
      console.error(`Video Load Error: Code ${errorCode}, Message: ${errorMsg}`);

      // Recover existing frames if decode error happens mid-stream
      if (frames.length > 0 && errorCode === 3) {
        console.warn(`Video processing encountered DECODE_ERROR but recovered ${frames.length} frames.`);
        onProgress(100);
        cleanup();
        resolve(frames);
        return;
      }

      let msg = "Unknown video loading error.";
      if (errorCode === 4) {
          msg = "Could not load video. The format might not be supported, or the server blocks cross-origin access (CORS).";
      } else if (errorCode === 3) {
          msg = "Video decoding failed. The file might be corrupted or the resolution/codec is too high for the browser's hardware decoder.";
      }

      cleanup();
      reject(new Error(msg));
    };

    const seekAndCapture = () => {
      if (isFinished) return;

      if (currentTime >= video.duration) {
        onProgress(100);
        cleanup();
        resolve(frames);
        return;
      }

      onProgress(Math.min(99, Math.round((currentTime / video.duration) * 100)));
      video.currentTime = currentTime;
    };

    video.onseeked = () => {
      if (isFinished) return;

      // Draw frame to capped-size canvas
      context.drawImage(video, 0, 0, canvas.width, canvas.height);

      try {
        const imageUrl = canvas.toDataURL('image/jpeg', 0.8);

        frames.push({
          timestamp: currentTime,
          imageUrl
        });

        currentTime += intervalSeconds;

        // Safety delay between seeks helps the hardware decoder (especially on macOS/iOS)
        // recover its state and prevents PIPELINE_ERROR_DECODE.
        setTimeout(() => {
            seekAndCapture();
        }, 400);

      } catch (e) {
        console.error("Frame extraction error:", e);
        cleanup();
        reject(new Error("Extraction Error: This might be due to CORS or memory pressure."));
      }
    };

    video.load();
  });
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Clapperboard, 
  Settings2, 
  Play, 
  Loader2, 
  Trash2,
  Download,
  RefreshCw,
  X,
  CheckSquare,
  Square,
  Info,
  Image as ImageIcon,
  ArrowUpDown,
  AlertCircle,
  BookOpen,
  Sparkles
} from 'lucide-react';

// Local imports
import VideoUploader from './components/VideoUploader';
import FrameCard from './components/FrameCard';
import StoryboardView from './components/StoryboardView';
import { extractFramesFromVideo } from './utils/videoProcessor';
import { generateFramePrompt, generateImage, generateStoryScript } from './services/geminiService';
import { FrameData, AnalysisStatus, AppSettings } from './types';

// Simple ID generator
const generateId = () => Math.random().toString(36).substring(2, 9);

type SortOption = 'time-asc' | 'time-desc' | 'prompt-asc' | 'prompt-desc';

const App: React.FC = () => {
  // State
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [frames, setFrames] = useState<FrameData[]>([]);
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [progress, setProgress] = useState(0);
  const [globalError, setGlobalError] = useState<string | null>(null);

  // Storyboard State
  const [storyScript, setStoryScript] = useState<string | null>(null);
  const [isStoryboardMode, setIsStoryboardMode] = useState(false);
  const [isGeneratingScript, setIsGeneratingScript] = useState(false);
  const [isBulkGeneratingImages, setIsBulkGeneratingImages] = useState(false);

  // Selection State
  const [selectedFrameIds, setSelectedFrameIds] = useState<Set<string>>(new Set());

  // Sorting State
  const [sortBy, setSortBy] = useState<SortOption>('time-asc');

  // Settings
  const [settings, setSettings] = useState<AppSettings>({
    samplingInterval: 3, // Default 3 seconds
    geminiModel: 'gemini-2.5-flash',
    customInstructions: '',
    promptTemplate: '{{PROMPT}}' // Default template
  });
  const [showSettings, setShowSettings] = useState(false);

  // Helper to ensure API Key is selected for paid models
  const ensureApiKey = async (): Promise<boolean> => {
    // @ts-ignore - aistudio is injected by the environment
    if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      // @ts-ignore
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
          // @ts-ignore
          await window.aistudio.openSelectKey();
          return true;
      }
      return true;
    }
    // Fallback if environment doesn't have the key selector (local dev mostly)
    return true; 
  };

  // Handlers
  const handleVideoSelected = (file: File | null, url: string | null) => {
    // Reset state
    setFrames([]);
    setSelectedFrameIds(new Set());
    setStatus(AnalysisStatus.IDLE);
    setProgress(0);
    setSortBy('time-asc');
    setGlobalError(null);
    setStoryScript(null);
    setIsStoryboardMode(false);

    if (file) {
      const objectUrl = URL.createObjectURL(file);
      setVideoUrl(objectUrl);
      setVideoFile(file);
    } else if (url) {
      setVideoUrl(url);
      setVideoFile(null);
    }
  };

  const handleReset = () => {
    if (videoUrl && videoFile) {
      URL.revokeObjectURL(videoUrl);
    }
    setVideoUrl(null);
    setVideoFile(null);
    setFrames([]);
    setSelectedFrameIds(new Set());
    setStatus(AnalysisStatus.IDLE);
    setProgress(0);
    setGlobalError(null);
    setStoryScript(null);
    setIsStoryboardMode(false);
  };

  const startAnalysis = async () => {
    if (!videoUrl) return;

    setStatus(AnalysisStatus.EXTRACTING);
    setProgress(0);
    setGlobalError(null);
    setSelectedFrameIds(new Set()); // Clear selection on new analysis
    setStoryScript(null); // Reset script

    try {
      // 1. Extract Frames
      const extractedFrames = await extractFramesFromVideo(
        videoUrl, 
        settings.samplingInterval,
        (prog) => setProgress(prog)
      );

      // Convert to FrameData structure
      const initialFrames: FrameData[] = extractedFrames.map(f => ({
        id: generateId(),
        timestamp: f.timestamp,
        imageUrl: f.imageUrl,
        prompt: null,
        isAnalyzing: true,
        error: undefined
      }));

      setFrames(initialFrames);
      setStatus(AnalysisStatus.ANALYZING);
      setProgress(0);

      // 2. Analyze Frames (Parallel but limited to avoid rate limits if possible)
      const BATCH_SIZE = 3;
      for (let i = 0; i < initialFrames.length; i += BATCH_SIZE) {
        const batch = initialFrames.slice(i, i + BATCH_SIZE);

        await Promise.all(batch.map(async (frame) => {
          try {
            const prompt = await generateFramePrompt(frame.imageUrl, {
              customInstructions: settings.customInstructions,
              template: settings.promptTemplate
            });
            setFrames(prev => prev.map(f => 
              f.id === frame.id 
                ? { ...f, prompt, isAnalyzing: false } 
                : f
            ));
          } catch (error) {
            setFrames(prev => prev.map(f => 
              f.id === frame.id 
                ? { ...f, isAnalyzing: false, error: 'Failed to analyze' } 
                : f
            ));
          }
        }));

        // Update progress roughly
        const currentProgress = Math.round(((i + BATCH_SIZE) / initialFrames.length) * 100);
        setProgress(Math.min(100, currentProgress));
      }

      setStatus(AnalysisStatus.COMPLETED);

    } catch (error) {
      console.error(error);
      setGlobalError(error instanceof Error ? error.message : "An unexpected error occurred during analysis.");
      setStatus(AnalysisStatus.ERROR);
    }
  };

  const handleRetryFrame = async (frameId: string) => {
    const frame = frames.find(f => f.id === frameId);
    if (!frame) return;

    setFrames(prev => prev.map(f => f.id === frameId ? { ...f, isAnalyzing: true, error: undefined } : f));

    try {
      const prompt = await generateFramePrompt(frame.imageUrl, {
        customInstructions: settings.customInstructions,
        template: settings.promptTemplate
      });
      setFrames(prev => prev.map(f => 
        f.id === frameId 
          ? { ...f, prompt, isAnalyzing: false } 
          : f
      ));
    } catch (error) {
      setFrames(prev => prev.map(f => 
        f.id === frameId 
          ? { ...f, isAnalyzing: false, error: 'Retry failed' } 
          : f
      ));
    }
  };

  const handleUpdatePrompt = (frameId: string, newPrompt: string) => {
    setFrames(prev => prev.map(f => 
      f.id === frameId 
        ? { ...f, prompt: newPrompt, isEdited: true } 
        : f
    ));
  };

  const processBatchImageGeneration = async (frameIds: string[]) => {
    if (frameIds.length === 0) return;

    const hasKey = await ensureApiKey();
    if (!hasKey) return;

    const framesToProcess = frames.filter(f => frameIds.includes(f.id) && f.prompt);

    // Set loading state for all frames in the batch
    setFrames(prev => prev.map(f => 
      frameIds.includes(f.id) && f.prompt ? { ...f, isGeneratingImage: true } : f
    ));

    // Process in small batches for images (high-latency model)
    const BATCH_SIZE = 2;
    for (let i = 0; i < framesToProcess.length; i += BATCH_SIZE) {
      const batch = framesToProcess.slice(i, i + BATCH_SIZE);
      await Promise.all(batch.map(async (frame) => {
        if (!frame.prompt) return;
        try {
          // Pass original frame as reference
          const generatedImage = await generateImage(frame.prompt, frame.imageUrl);
          setFrames(prev => prev.map(f => 
            f.id === frame.id ? { ...f, generatedImage, isGeneratingImage: false } : f
          ));
        } catch (e) {
          console.error("Batch image gen error", e);
          setFrames(prev => prev.map(f => 
            f.id === frame.id ? { ...f, isGeneratingImage: false } : f
          ));
        }
      }));
    }
  };

  const handleGenerateImage = async (frameId: string, referenceImageUrl?: string) => {
    const frame = frames.find(f => f.id === frameId);
    if (!frame || !frame.prompt) return;

    const hasKey = await ensureApiKey();
    if (!hasKey) return;

    setFrames(prev => prev.map(f => f.id === frameId ? { ...f, isGeneratingImage: true } : f));

    try {
        const refImage = referenceImageUrl || frame.imageUrl;
        const generatedImage = await generateImage(frame.prompt, refImage);
        setFrames(prev => prev.map(f => 
            f.id === frameId ? { ...f, generatedImage, isGeneratingImage: false } : f
        ));
    } catch (e) {
        console.error("Failed to generate image", e);
        setFrames(prev => prev.map(f => 
            f.id === frameId ? { ...f, isGeneratingImage: false } : f
        ));
        alert("Failed to generate image. Please ensure you have selected a valid project/key.");
    }
  };

  const handleGenerateAllImages = async () => {
    const frameIdsWithPrompts = frames
      .filter(f => f.prompt && !f.generatedImage)
      .map(f => f.id);

    if (frameIdsWithPrompts.length === 0) {
      alert("No frames available for image generation (all frames may already have images or missing prompts).");
      return;
    }

    if (!window.confirm(`Generate AI images for all ${frameIdsWithPrompts.length} remaining frames? This may take several minutes.`)) {
      return;
    }

    setIsBulkGeneratingImages(true);
    try {
      await processBatchImageGeneration(frameIdsWithPrompts);
    } finally {
      setIsBulkGeneratingImages(false);
    }
  };

  const handleCreateStoryboard = async () => {
    if (storyScript) {
        setIsStoryboardMode(true);
        return;
    }

    const validPrompts = frames.filter(f => f.prompt).map(f => f.prompt as string);
    if (validPrompts.length === 0) return;

    setIsGeneratingScript(true);
    try {
        const script = await generateStoryScript(validPrompts);
        setStoryScript(script);
        setIsStoryboardMode(true);
    } catch (e) {
        console.error("Failed to generate storyboard script", e);
        alert("Failed to generate storyboard script.");
    } finally {
        setIsGeneratingScript(false);
    }
  };

  const handleDownloadAll = () => {
    const textContent = frames
      .filter(f => f.prompt)
      .map(f => `[${f.timestamp.toFixed(2)}s]\n${f.prompt}\n`)
      .join('\n-------------------\n\n');

    const blob = new Blob([textContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'prompts.txt';
    a.click();
    URL.revokeObjectURL(url);
  };

  // Selection Handlers
  const toggleFrameSelection = (id: string) => {
    const newSelected = new Set(selectedFrameIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedFrameIds(newSelected);
  };

  const handleSelectAll = () => {
    if (selectedFrameIds.size === frames.length) {
      setSelectedFrameIds(new Set());
    } else {
      setSelectedFrameIds(new Set(frames.map(f => f.id)));
    }
  };

  const handleBulkDelete = () => {
    if (window.confirm(`Delete ${selectedFrameIds.size} selected frames?`)) {
      setFrames(prev => prev.filter(f => !selectedFrameIds.has(f.id)));
      setSelectedFrameIds(new Set());
    }
  };

  const handleBulkRegenerate = async () => {
    const idsToProcess = Array.from(selectedFrameIds);
    if (idsToProcess.length === 0) return;

    setFrames(prev => prev.map(f => 
      selectedFrameIds.has(f.id) 
        ? { ...f, isAnalyzing: true, error: undefined, prompt: null }
        : f
    ));
    setSelectedFrameIds(new Set());

    const BATCH_SIZE = 3;
    const framesToProcess = frames.filter(f => selectedFrameIds.has(f.id));

    for (let i = 0; i < framesToProcess.length; i += BATCH_SIZE) {
       const batch = framesToProcess.slice(i, i + BATCH_SIZE);
       await Promise.all(batch.map(async (frame) => {
          try {
              const prompt = await generateFramePrompt(frame.imageUrl, {
                customInstructions: settings.customInstructions,
                template: settings.promptTemplate
              });
               setFrames(prev => prev.map(f => 
                f.id === frame.id 
                  ? { ...f, prompt, isAnalyzing: false } 
                  : f
              ));
          } catch (e) {
               setFrames(prev => prev.map(f => 
                f.id === frame.id 
                  ? { ...f, isAnalyzing: false, error: 'Regeneration failed' } 
                  : f
              ));
          }
       }));
    }
  };

  const handleBulkGenerateImages = async () => {
    const idsToProcess = Array.from(selectedFrameIds);
    if (idsToProcess.length === 0) return;

    setSelectedFrameIds(new Set()); // Clear selection
    await processBatchImageGeneration(idsToProcess);
  };

  // Sorting Logic
  const sortedFrames = useMemo(() => {
    const sorted = [...frames];
    switch (sortBy) {
      case 'time-desc':
        return sorted.sort((a, b) => b.timestamp - a.timestamp);
      case 'prompt-asc':
        return sorted.sort((a, b) => (a.prompt?.length || 0) - (b.prompt?.length || 0));
      case 'prompt-desc':
        return sorted.sort((a, b) => (b.prompt?.length || 0) - (a.prompt?.length || 0));
      case 'time-asc':
      default:
        return sorted.sort((a, b) => a.timestamp - b.timestamp);
    }
  }, [frames, sortBy]);

  // Cleanup effect
  useEffect(() => {
    return () => {
      if (videoUrl && videoFile) {
        URL.revokeObjectURL(videoUrl);
      }
    };
  }, []);

  return (
    <div className="min-h-screen flex flex-col pb-24">
      {/* Header */}
      <header className="bg-slate-900/50 backdrop-blur-md border-b border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-600 rounded-lg">
              <Clapperboard className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-400">
              FrameFlow
            </h1>
          </div>

          <div className="flex items-center gap-2">
            <button 
              onClick={() => setShowSettings(!showSettings)}
              className={`p-2 rounded-lg transition-colors ${showSettings ? 'bg-slate-800 text-blue-400' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
              title="Settings"
            >
              <Settings2 className="w-5 h-5" />
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow p-6">
        {isStoryboardMode && storyScript ? (
            <StoryboardView 
                frames={frames} 
                script={storyScript} 
                onBack={() => setIsStoryboardMode(false)} 
            />
        ) : (
        <div className="max-w-7xl mx-auto space-y-8">

          {/* Settings Panel */}
          {showSettings && (
            <div className="bg-slate-800 border border-slate-700 rounded-xl p-6 animate-fadeIn shadow-2xl">
              <div className="flex items-center justify-between mb-6 border-b border-slate-700 pb-4">
                 <h3 className="text-lg font-semibold text-slate-200">Analysis Settings</h3>
                 <button onClick={() => setShowSettings(false)} className="text-slate-500 hover:text-white">
                   <X className="w-5 h-5" />
                 </button>
              </div>

              <div className="grid md:grid-cols-2 gap-8">
                {/* Left Column */}
                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-sm font-medium text-slate-400">
                      Sampling Interval (seconds)
                    </label>
                    <div className="flex items-center gap-4">
                      <input 
                        type="range" 
                        min="1" 
                        max="10" 
                        step="1"
                        value={settings.samplingInterval}
                        onChange={(e) => setSettings({...settings, samplingInterval: parseInt(e.target.value)})}
                        className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                        disabled={status !== AnalysisStatus.IDLE}
                      />
                      <span className="text-white font-mono w-12 text-center bg-slate-700 rounded py-1 text-sm">
                        {settings.samplingInterval}s
                      </span>
                    </div>
                    <p className="text-xs text-slate-500">
                      Extracts a frame every X seconds. Lower interval = more frames.
                    </p>
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-medium text-slate-400">
                      Custom Prompt Instructions
                    </label>
                    <textarea
                      className="w-full h-32 bg-slate-900 border border-slate-700 rounded-lg p-3 text-sm text-slate-200 focus:ring-2 focus:ring-blue-500 outline-none resize-none font-sans"
                      placeholder="e.g., 'Describe the scene in the style of a 90s anime', 'Focus on the lighting and textures'..."
                      value={settings.customInstructions}
                      onChange={(e) => setSettings({...settings, customInstructions: e.target.value})}
                    ></textarea>
                  </div>
                </div>

                {/* Right Column - Template */}
                <div className="space-y-2">
                    <div className="flex items-center justify-between">
                        <label className="text-sm font-medium text-slate-400">
                           Output Prompt Template
                        </label>
                        <div className="group relative">
                           <Info className="w-4 h-4 text-slate-500 hover:text-blue-400 cursor-help" />
                           <div className="absolute right-0 top-6 w-64 p-3 bg-slate-900 border border-slate-700 rounded-lg shadow-xl text-xs text-slate-300 z-50 hidden group-hover:block">
                              Use <code>{`{{PROMPT}}`}</code> as the main placeholder. You can also define specific variables like <code>{`{{SUBJECT}}`}</code> or <code>{`{{STYLE}}`}</code> and the AI will try to fill them.
                           </div>
                        </div>
                    </div>

                    <textarea
                      className="w-full h-[220px] bg-slate-900 border border-slate-700 rounded-lg p-3 text-sm text-slate-200 focus:ring-2 focus:ring-blue-500 outline-none resize-none font-mono leading-relaxed"
                      placeholder="Define the structure of the output..."
                      value={settings.promptTemplate}
                      onChange={(e) => setSettings({...settings, promptTemplate: e.target.value})}
                    ></textarea>

                    <div className="flex gap-2 text-xs">
                        <button 
                            onClick={() => setSettings({...settings, promptTemplate: '{{PROMPT}} --ar 16:9 --v 6.0'})}
                            className="px-2 py-1 bg-slate-700 rounded hover:bg-slate-600 text-slate-300"
                        >
                            Midjourney Preset
                        </button>
                        <button 
                            onClick={() => setSettings({...settings, promptTemplate: 'Subject: {{SUBJECT}}\nAction: {{ACTION}}\nStyle: {{STYLE}}'})}
                            className="px-2 py-1 bg-slate-700 rounded hover:bg-slate-600 text-slate-300"
                        >
                            Structured Preset
                        </button>
                         <button 
                            onClick={() => setSettings({...settings, promptTemplate: '{{PROMPT}}'})}
                            className="px-2 py-1 bg-slate-700 rounded hover:bg-slate-600 text-slate-300"
                        >
                            Reset
                        </button>
                    </div>
                </div>
              </div>
            </div>
          )}

          {/* Upload / Preview Section */}
          {!videoUrl ? (
            <div className="py-12">
              <VideoUploader onVideoSelected={handleVideoSelected} disabled={false} />
            </div>
          ) : (
            <div className="space-y-6">
              {/* Video Player & Controls */}
              <div className="bg-slate-900 rounded-2xl overflow-hidden border border-slate-800 shadow-2xl">
                 <div className="aspect-video bg-black max-h-[500px] flex items-center justify-center relative">
                   <video 
                     src={videoUrl} 
                     controls 
                     className="w-full h-full object-contain" 
                   />
                 </div>

                 <div className="p-4 bg-slate-800/50 flex flex-wrap items-center justify-between gap-4">
                   <div className="flex items-center gap-4">
                      {status === AnalysisStatus.IDLE ? (
                        <button
                          onClick={startAnalysis}
                          className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-lg font-semibold transition-all shadow-lg shadow-blue-900/20 active:scale-95"
                        >
                          <Play className="w-5 h-5 fill-current" /> Start Analysis
                        </button>
                      ) : status === AnalysisStatus.ERROR ? (
                        <div className="flex items-center gap-2 text-red-400 bg-red-400/10 px-4 py-2 rounded-lg border border-red-400/20 animate-fadeIn">
                           <AlertCircle className="w-5 h-5" />
                           <span className="font-medium text-sm">{globalError || "Analysis failed"}</span>
                        </div>
                      ) : status !== AnalysisStatus.COMPLETED ? (
                        <div className="flex items-center gap-3 px-6 py-2.5 bg-slate-700 rounded-lg">
                          <Loader2 className="w-5 h-5 animate-spin text-blue-400" />
                          <span className="text-slate-200 font-medium">
                            {status === AnalysisStatus.EXTRACTING ? 'Extracting Frames...' : 'Generating Prompts...'}
                          </span>
                          <span className="text-slate-400 text-sm">({progress}%)</span>
                        </div>
                      ) : (
                        <div className="flex items-center gap-2 text-green-400 font-medium px-4">
                          Analysis Complete ({frames.length} frames)
                        </div>
                      )}
                   </div>

                   <div className="flex items-center gap-3">
                     {status === AnalysisStatus.COMPLETED && (
                       <>
                        <button
                          onClick={handleGenerateAllImages}
                          disabled={isBulkGeneratingImages}
                          className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white rounded-lg text-sm font-semibold transition-all shadow-lg shadow-purple-900/20 active:scale-95 disabled:opacity-50"
                        >
                          {isBulkGeneratingImages ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                          {isBulkGeneratingImages ? 'Generating All...' : 'Generate All Images'}
                        </button>
                        <button
                          onClick={handleCreateStoryboard}
                          disabled={isGeneratingScript}
                          className="flex items-center gap-2 px-4 py-2 bg-purple-600 hover:bg-purple-500 text-white rounded-lg text-sm transition-colors disabled:opacity-50"
                        >
                          {isGeneratingScript ? <Loader2 className="w-4 h-4 animate-spin" /> : <BookOpen className="w-4 h-4" />}
                          {isGeneratingScript ? 'Generating Story...' : (storyScript ? 'View Storyboard' : 'Create Storyboard')}
                        </button>
                        <button
                          onClick={handleDownloadAll}
                          className="flex items-center gap-2 px-4 py-2 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-sm transition-colors"
                        >
                          <Download className="w-4 h-4" /> Export
                        </button>
                       </>
                     )}
                     <button
                       onClick={handleReset}
                       className="flex items-center gap-2 px-4 py-2 bg-red-500/10 hover:bg-red-500/20 text-red-400 rounded-lg text-sm transition-colors"
                     >
                       <Trash2 className="w-4 h-4" /> Reset
                     </button>
                   </div>
                 </div>

                 {/* Progress Bar */}
                 {(status === AnalysisStatus.EXTRACTING || status === AnalysisStatus.ANALYZING) && (
                   <div className="h-1 w-full bg-slate-800">
                     <div 
                       className="h-full bg-blue-500 transition-all duration-300"
                       style={{ width: `${progress}%` }}
                     ></div>
                   </div>
                 )}
              </div>

              {/* Results Grid */}
              {frames.length > 0 && (
                <div className="animate-fadeIn">
                   <div className="flex items-center justify-between mb-4 sticky top-20 z-40 bg-slate-900/90 backdrop-blur-sm p-4 rounded-xl border border-slate-800">
                     <div className="flex items-center gap-4">
                        <button 
                            onClick={handleSelectAll}
                            className="flex items-center gap-2 text-sm text-slate-300 hover:text-white transition-colors"
                        >
                           {selectedFrameIds.size === frames.length ? <CheckSquare className="w-4 h-4 text-blue-400" /> : <Square className="w-4 h-4" />}
                           {selectedFrameIds.size === frames.length ? 'Deselect All' : 'Select All'}
                        </button>
                        <h2 className="text-xl font-bold text-white hidden sm:block">Generated Prompts</h2>
                     </div>

                     <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <label className="text-xs text-slate-400 hidden md:block">Sort by:</label>
                            <div className="relative">
                                <ArrowUpDown className="w-3 h-3 text-slate-500 absolute left-2 top-1/2 -translate-y-1/2 pointer-events-none" />
                                <select 
                                    value={sortBy} 
                                    onChange={(e) => setSortBy(e.target.value as SortOption)}
                                    className="bg-slate-800 border border-slate-700 rounded-lg text-sm text-slate-300 pl-7 pr-3 py-1.5 focus:ring-1 focus:ring-blue-500 outline-none appearance-none cursor-pointer hover:bg-slate-750 transition-colors"
                                >
                                    <option value="time-asc">Time (Oldest)</option>
                                    <option value="time-desc">Time (Newest)</option>
                                    <option value="prompt-asc">Prompt Length (Short)</option>
                                    <option value="prompt-desc">Prompt Length (Long)</option>
                                </select>
                            </div>
                        </div>
                        <span className="text-slate-500 text-sm border-l border-slate-700 pl-4">{frames.length} frames</span>
                     </div>
                   </div>

                   <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                     {sortedFrames.map((frame) => (
                       <FrameCard 
                         key={frame.id} 
                         frame={frame} 
                         onRetry={handleRetryFrame}
                         isSelected={selectedFrameIds.has(frame.id)}
                         onToggleSelect={toggleFrameSelection}
                         onGenerateImage={handleGenerateImage}
                         onUpdatePrompt={handleUpdatePrompt}
                       />
                     ))}
                   </div>
                </div>
              )}
            </div>
          )}
        </div>
        )}
      </main>

      {/* Bulk Actions Floating Bar - Only show when NOT in storyboard mode */}
      {!isStoryboardMode && selectedFrameIds.size > 0 && (
        <div className="fixed bottom-8 left-1/2 transform -translate-x-1/2 bg-slate-800 border border-slate-600 shadow-2xl rounded-full px-8 py-4 flex items-center gap-6 z-50 animate-bounce-in">
            <span className="text-white font-medium whitespace-nowrap">{selectedFrameIds.size} Selected</span>
            <div className="h-6 w-px bg-slate-600"></div>

            <button 
              onClick={handleBulkRegenerate} 
              className="flex items-center gap-2 text-blue-400 hover:text-blue-300 transition-colors font-medium text-sm"
              title="Regenerate Prompts"
            >
                <RefreshCw className="w-4 h-4" /> Regen Prompts
            </button>

            <button 
              onClick={handleBulkGenerateImages} 
              className="flex items-center gap-2 text-purple-400 hover:text-purple-300 transition-colors font-medium text-sm"
              title="Generate Images for Selected"
            >
                <ImageIcon className="w-4 h-4" /> Gen Images
            </button>

            <button 
              onClick={handleBulkDelete} 
              className="flex items-center gap-2 text-red-400 hover:text-red-300 transition-colors font-medium text-sm"
              title="Delete Frames"
            >
                <Trash2 className="w-4 h-4" /> Delete
            </button>

            <div className="h-6 w-px bg-slate-600"></div>

            <button 
              onClick={() => setSelectedFrameIds(new Set())} 
              className="text-slate-400 hover:text-white transition-colors p-1 rounded-full hover:bg-slate-700"
              title="Clear Selection"
            >
                <X className="w-5 h-5" />
            </button>
        </div>
      )}
    </div>
  );
};

