import React, { useState, useRef, useEffect } from 'react';
import { Copy, Check, Loader2, RefreshCw, Image as ImageIcon, Eye, Film, Download, ChevronDown, CheckCircle, Edit2, Save, X, Sparkles, ArrowUp } from 'lucide-react';
import { FrameData } from '../types';

interface FrameCardProps {
  frame: FrameData;
  onRetry: (frameId: string) => void;
  isSelected: boolean;
  onToggleSelect: (frameId: string) => void;
  onGenerateImage: (frameId: string, referenceImageUrl?: string) => void;
  onUpscaleImage: (frameId: string) => void;
  onUpdatePrompt: (frameId: string, newPrompt: string) => void;
}

type DownloadQuality = 'original' | '720p' | '1080p';

const FrameCard: React.FC<FrameCardProps> = ({ 
  frame, 
  onRetry, 
  isSelected, 
  onToggleSelect,
  onGenerateImage,
  onUpscaleImage,
  onUpdatePrompt
}) => {
  const [copied, setCopied] = useState(false);
  const [viewMode, setViewMode] = useState<'original' | 'generated'>('original');
  const [isEditing, setIsEditing] = useState(false);
  const [editPrompt, setEditPrompt] = useState('');

  // Download Quality State
  const [downloadQuality, setDownloadQuality] = useState<DownloadQuality>(() => {
    return (localStorage.getItem('frameflow-download-quality') as DownloadQuality) || 'original';
  });
  const [showQualityMenu, setShowQualityMenu] = useState(false);
  const [isProcessingDownload, setIsProcessingDownload] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  const handleQualityChange = (quality: DownloadQuality) => {
    setDownloadQuality(quality);
    localStorage.setItem('frameflow-download-quality', quality);
    setShowQualityMenu(false);
  };

  // Close menu on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowQualityMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleCopy = async () => {
    if (frame.prompt) {
      await navigator.clipboard.writeText(frame.prompt);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const handleStartEdit = () => {
    setEditPrompt(frame.prompt || '');
    setIsEditing(true);
  };

  const handleSaveEdit = () => {
    if (editPrompt.trim() !== frame.prompt) {
      onUpdatePrompt(frame.id, editPrompt.trim());
    }
    setIsEditing(false);
  };

  const handleCancelEdit = () => {
    setIsEditing(false);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Automatically switch to generated view if image is newly created
  useEffect(() => {
    if (frame.generatedImage && !frame.isGeneratingImage && !frame.isUpscaling) {
      setViewMode('generated');
    }
  }, [frame.generatedImage, frame.isGeneratingImage, frame.isUpscaling]);

  // Determine which image to show
  const activeImage = viewMode === 'generated' && frame.generatedImage ? frame.generatedImage : frame.imageUrl;

  const processImageForDownload = async (base64Str: string, quality: DownloadQuality): Promise<string> => {
    if (quality === 'original') return base64Str;

    return new Promise((resolve, reject) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const targetHeight = quality === '720p' ? 720 : 1080;
        const aspectRatio = img.width / img.height;
        const targetWidth = Math.round(targetHeight * aspectRatio);

        const canvas = document.createElement('canvas');
        canvas.width = targetWidth;
        canvas.height = targetHeight;
        const ctx = canvas.getContext('2d');

        if (!ctx) {
          resolve(base64Str);
          return;
        }

        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';
        ctx.drawImage(img, 0, 0, targetWidth, targetHeight);

        resolve(canvas.toDataURL('image/jpeg', 0.92));
      };
      img.onerror = (e) => reject(e);
    });
  };

  const handleDownload = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isProcessingDownload) return;

    setIsProcessingDownload(true);
    try {
        const processedImage = await processImageForDownload(activeImage, downloadQuality);

        const link = document.createElement('a');
        link.href = processedImage;
        const prefix = viewMode === 'generated' ? 'ai-generated' : 'frame';
        const qualitySuffix = downloadQuality === 'original' ? '' : `-${downloadQuality}`;
        link.download = `frameflow-${prefix}-${Math.floor(frame.timestamp)}${qualitySuffix}.jpg`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } catch (error) {
        console.error("Download processing failed", error);
        alert("Failed to process image for download.");
    } finally {
        setIsProcessingDownload(false);
    }
  };

  return (
    <div className={`
      relative bg-slate-800 rounded-xl overflow-hidden border transition-all flex flex-col h-full shadow-lg group
      ${isSelected ? 'border-blue-500 ring-1 ring-blue-500' : 'border-slate-700 hover:border-slate-600'}
    `}>
      {/* Selection Checkbox Overlay */}
      <div className="absolute top-2 left-2 z-10">
        <input
          type="checkbox"
          checked={isSelected}
          onChange={() => onToggleSelect(frame.id)}
          className="w-5 h-5 rounded border-slate-600 bg-slate-900/80 text-blue-600 focus:ring-blue-500 focus:ring-offset-slate-800 cursor-pointer backdrop-blur-sm"
        />
      </div>

      {/* Image Preview */}
      <div className="relative aspect-video bg-black overflow-hidden group/image">
        <img 
          src={activeImage} 
          alt={`Frame at ${formatTime(frame.timestamp)}`}
          className="w-full h-full object-contain"
        />

        {/* Top Right Overlay: Timestamp & Download Status */}
        <div className="absolute top-2 right-2 flex items-center gap-2 z-10">
            <button
                onClick={handleDownload}
                disabled={isProcessingDownload}
                className="bg-black/60 hover:bg-black/80 backdrop-blur-sm p-1.5 rounded text-white transition-colors flex items-center gap-1"
                title={`Download Image (${downloadQuality})`}
            >
                {isProcessingDownload ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Download className="w-3.5 h-3.5" />}
                {downloadQuality !== 'original' && <span className="text-[10px] font-medium leading-none uppercase">{downloadQuality}</span>}
            </button>
            <div className="bg-black/60 backdrop-blur-sm px-2 py-1 rounded text-xs font-mono text-white">
              {formatTime(frame.timestamp)}
            </div>
        </div>

        {/* View Toggle (Original vs AI Gen) - Always visible if generated image exists */}
        {frame.generatedImage && (
            <div className="absolute bottom-2 left-1/2 -translate-x-1/2 flex bg-slate-900/90 backdrop-blur-md rounded-full p-1 border border-slate-700/50 shadow-lg z-10">
                <button
                    onClick={(e) => { e.stopPropagation(); setViewMode('original'); }}
                    className={`p-1.5 rounded-full transition-colors flex items-center gap-1.5 px-3 ${viewMode === 'original' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-400 hover:text-white'}`}
                    title="Original Frame"
                >
                    <Film className="w-3 h-3" />
                    <span className="text-[10px] font-medium">Original</span>
                </button>
                <button
                    onClick={(e) => { e.stopPropagation(); setViewMode('generated'); }}
                    className={`p-1.5 rounded-full transition-colors flex items-center gap-1.5 px-3 ${viewMode === 'generated' ? 'bg-blue-600 text-white shadow-sm' : 'text-slate-400 hover:text-white'}`}
                    title="AI Generated Image"
                >
                    <Eye className="w-3 h-3" />
                    <span className="text-[10px] font-medium">AI Gen</span>
                </button>
            </div>
        )}

        {/* Loading Overlays */}
        {frame.isGeneratingImage && (
            <div className="absolute inset-0 bg-black/70 backdrop-blur-[2px] flex flex-col items-center justify-center z-20">
                <Loader2 className="w-8 h-8 text-blue-400 animate-spin mb-2" />
                <span className="text-xs text-blue-200 font-medium">Generating Image...</span>
            </div>
        )}

        {frame.isUpscaling && (
            <div className="absolute inset-0 bg-indigo-900/70 backdrop-blur-[3px] flex flex-col items-center justify-center z-20">
                <div className="relative mb-3">
                    <Loader2 className="w-10 h-10 text-indigo-300 animate-spin" />
                    <Sparkles className="w-4 h-4 text-white absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
                </div>
                <span className="text-sm text-white font-bold tracking-tight mb-1">AI Upscaling 2K</span>
                <span className="text-[10px] text-indigo-200 opacity-80 uppercase tracking-widest">Deep Scanning & Enhancing</span>
            </div>
        )}
      </div>

      {/* Content Area */}
      <div className="p-4 flex flex-col flex-grow">
        {/* Header - Edited & Quality Status */}
        <div className="flex items-center gap-2 mb-2 flex-wrap">
          {frame.isEdited && !isEditing && (
              <span className="text-[10px] uppercase font-bold text-amber-400 border border-amber-500/30 bg-amber-500/10 px-1.5 py-0.5 rounded">
                  Edited
              </span>
          )}
          {frame.generatedImage && !frame.isUpscaling && (
              <span className="text-[10px] uppercase font-bold text-indigo-400 border border-indigo-500/30 bg-indigo-500/10 px-1.5 py-0.5 rounded flex items-center gap-1">
                  <Sparkles className="w-2.5 h-2.5" /> High Res (2K)
              </span>
          )}
        </div>

        <div className="flex-grow relative">
          {frame.isAnalyzing ? (
            <div className="flex items-center gap-2 text-blue-400 text-sm font-medium animate-pulse py-4">
              <Loader2 className="w-4 h-4 animate-spin" />
              Generating Prompt...
            </div>
          ) : frame.error ? (
             <div className="flex flex-col gap-2 py-2">
               <p className="text-red-400 text-sm">Failed to generate.</p>
               <button 
                 onClick={() => onRetry(frame.id)}
                 className="flex items-center gap-1 text-xs text-slate-400 hover:text-white transition-colors"
               >
                 <RefreshCw className="w-3 h-3" /> Retry
               </button>
             </div>
          ) : isEditing ? (
             <div className="space-y-2">
                 <textarea
                    value={editPrompt}
                    onChange={(e) => setEditPrompt(e.target.value)}
                    className="w-full h-32 bg-slate-900 border border-slate-600 rounded-lg p-2 text-sm text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                    placeholder="Edit your prompt here..."
                    autoFocus
                 />
                 <div className="flex items-center justify-end gap-2">
                     <button
                        onClick={handleCancelEdit}
                        className="px-2 py-1 bg-slate-700 hover:bg-slate-600 text-white text-xs rounded flex items-center gap-1"
                     >
                        <X className="w-3 h-3" /> Cancel
                     </button>
                     <button
                        onClick={handleSaveEdit}
                        className="px-2 py-1 bg-blue-600 hover:bg-blue-500 text-white text-xs rounded flex items-center gap-1"
                     >
                        <Save className="w-3 h-3" /> Save
                     </button>
                 </div>
             </div>
          ) : (
            <p className="text-sm text-slate-300 leading-relaxed line-clamp-6 group-hover:line-clamp-none transition-all">
              {frame.prompt}
            </p>
          )}
        </div>

        {/* Action Footer */}
        {frame.prompt && !isEditing && (
          <div className="pt-4 mt-2 border-t border-slate-700/50 flex flex-col gap-3">
            <div className="flex items-center justify-between gap-2">
                <div className="flex items-center gap-2">
                    <button
                        onClick={() => onGenerateImage(frame.id, frame.imageUrl)}
                        disabled={frame.isGeneratingImage || frame.isUpscaling}
                        className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium border transition-all shadow-sm ${
                            frame.generatedImage 
                            ? 'bg-slate-800 text-purple-300 border-purple-500/30 hover:bg-purple-900/20' 
                            : 'bg-gradient-to-r from-indigo-600 to-purple-600 text-white border-transparent hover:from-indigo-500 hover:to-purple-500 shadow-purple-900/20'
                        } disabled:opacity-50`}
                        title={frame.generatedImage ? "Regenerate AI Image" : "Generate AI Image from prompt"}
                    >
                        {frame.isGeneratingImage ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <ImageIcon className="w-3.5 h-3.5" />}
                        {frame.generatedImage ? 'Regenerate' : 'Generate Image'}
                    </button>

                    {frame.generatedImage && (
                        <button
                            onClick={() => onUpscaleImage(frame.id)}
                            disabled={frame.isGeneratingImage || frame.isUpscaling}
                            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold bg-gradient-to-r from-indigo-600 to-rose-600 text-white border-transparent hover:from-indigo-500 hover:to-rose-500 shadow-sm disabled:opacity-50 transition-all active:scale-95"
                            title="AI Upscale to 2K (Enhance details)"
                        >
                            {frame.isUpscaling ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <ArrowUp className="w-3.5 h-3.5" />}
                            Upscale (2K)
                        </button>
                    )}
                </div>

                <div className="flex items-center gap-1">
                    <button
                        onClick={handleStartEdit}
                        className="p-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-700 transition-colors"
                        title="Edit Prompt"
                    >
                        <Edit2 className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={handleCopy}
                      className={`
                        flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium transition-all
                        ${copied 
                          ? 'bg-green-500/20 text-green-400 border border-green-500/50' 
                          : 'bg-slate-700 text-slate-200 hover:bg-blue-600 hover:text-white'}
                      `}
                    >
                      {copied ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
                    </button>
                </div>
            </div>

            {/* Quality Select for Download */}
            <div className="relative" ref={menuRef}>
                <div className="flex items-center w-full rounded-lg bg-slate-700/50 text-slate-300 hover:bg-slate-600/50 transition-all border border-slate-700 hover:border-slate-500">
                    <button
                        onClick={handleDownload}
                        disabled={isProcessingDownload}
                        className="flex-grow flex items-center justify-center gap-2 px-3 py-2 text-xs font-semibold hover:text-white border-r border-slate-600"
                        title={`Download (${downloadQuality})`}
                    >
                        {isProcessingDownload ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Download className="w-3.5 h-3.5" />}
                        Download Current Image
                    </button>
                    <button
                        onClick={() => setShowQualityMenu(!showQualityMenu)}
                        className="px-3 py-2 hover:text-white flex items-center gap-1 text-[10px] font-mono"
                        title="Download Quality Settings"
                    >
                        {downloadQuality.toUpperCase()}
                        <ChevronDown className="w-3 h-3" />
                    </button>
                </div>

                {/* Quality Dropdown Menu */}
                {showQualityMenu && (
                    <div className="absolute bottom-full left-0 right-0 mb-2 bg-slate-800 border border-slate-700 rounded-lg shadow-2xl z-50 overflow-hidden">
                        <div className="px-3 py-2 text-[10px] font-bold text-slate-500 uppercase tracking-wider bg-slate-900/50">
                            Download Quality
                        </div>
                        <div className="p-1">
                            {(['original', '1080p', '720p'] as DownloadQuality[]).map((q) => (
                                <button
                                    key={q}
                                    onClick={() => handleQualityChange(q)}
                                    className={`w-full text-left px-3 py-2 text-xs rounded flex items-center justify-between ${
                                        downloadQuality === q ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-700'
                                    }`}
                                >
                                    <span className="capitalize">{q}</span>
                                    {downloadQuality === q && <CheckCircle className="w-3 h-3" />}
                                </button>
                            ))}
                        </div>
                    </div>
                )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

